func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := schemeFromHeader(c.request.Header.Get(HeaderXForwardedProto)); scheme != "" {
		return scheme
	}
	if scheme := schemeFromHeader(c.request.Header.Get(HeaderXForwardedProtocol)); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := schemeFromHeader(c.request.Header.Get(HeaderXUrlScheme)); scheme != "" {
		return scheme
	}
	return "http"
}

// schemeFromHeader returns the given header value when it holds a valid HTTP
// scheme (`http` or `https`), otherwise it returns an empty string so the
// caller can fall back to the next header.
func schemeFromHeader(scheme string) string {
	if strings.EqualFold(scheme, "http") || strings.EqualFold(scheme, "https") {
		return scheme
	}
	return ""
}

